insert into public.question_rubrics
  (question_id, course_id, lesson_id, code_en, code_tr, key_points_en, key_points_tr)
values
  (
    $q$py-u01-l1-q6$q$,
    $q$python$q$,
    $q$py-u01-l1$q$,
    $q$# This shows two numbers
print(6)
print(9)$q$,
    $q$# Bu iki sayıyı gösterir
print(6)
print(9)$q$,
    $q$["the first print outputs 6","the second print outputs 9","each print creates a new line"]$q$::jsonb,
    $q$["ilk print 6'yı çıktı verir","ikinci print 9'u çıktı verir","her print yeni bir satır oluşturur"]$q$::jsonb
  ),
  (
    $q$py-u01-l2-q6$q$,
    $q$python$q$,
    $q$py-u01-l2$q$,
    $q$# Announce the winner
print("Winner:", "Alice", "Score:", 98)$q$,
    $q$# Kazananı duyur
print("Winner:", "Alice", "Score:", 98)$q$,
    $q$["uses a comment to explain the code's purpose","prints four separate values using commas","Python joins them with spaces on one line"]$q$::jsonb,
    $q$["kodun amacını açıklamak için bir yorum kullanır","virgülleri kullanarak dört ayrı değeri yazdırır","Python onları tek satırda boşluklarla birleştirir"]$q$::jsonb
  ),
  (
    $q$py-u01-l3-q6$q$,
    $q$python$q$,
    $q$py-u01-l3$q$,
    $q$# Store a book title
title = "Python Basics"
print("Reading:", title)$q$,
    $q$# Bir kitap başlığını sakla
title = "Python Basics"
print("Reading:", title)$q$,
    $q$["creates a variable called title","stores the text Python Basics in that variable","prints Reading followed by the value of the title variable"]$q$::jsonb,
    $q$["title adlı bir değişken oluşturur","Python Basics metnini bu değişkende saklar","Reading'i takip eden title değişkeninin değerini yazdırır"]$q$::jsonb
  ),
  (
    $q$py-u01-l4-q6$q$,
    $q$python$q$,
    $q$py-u01-l4$q$,
    $q$# Show a greeting
name = "Jordan"
greeting = "Hi"
print(greeting, "to", name)$q$,
    $q$# Bir selamlamayı göster
name = "Jordan"
greeting = "Hi"
print(greeting, "to", name)$q$,
    $q$["creates variables in order: name then greeting","each variable stores a text value","prints all three values separated by commas"]$q$::jsonb,
    $q$["sırayla değişkenler oluşturur: name sonra greeting","her değişken bir metin değerini depolar","virgüllerle ayrılmış üç değeri yazdırır"]$q$::jsonb
  ),
  (
    $q$py-u02-l1-q6$q$,
    $q$python$q$,
    $q$py-u02-l1$q$,
    $q$# Store and display information
first_name = "Sarah"
last_name = "Chen"
print(first_name)
print(last_name)$q$,
    $q$# Bilgiyi sakla ve göster
first_name = "Sarah"
last_name = "Chen"
print(first_name)
print(last_name)$q$,
    $q$["creates a variable first_name and stores the text Sarah","creates a variable last_name and stores the text Chen","prints each variable on its own line"]$q$::jsonb,
    $q$["first_name değişkenini oluşturur ve Sarah metnini saklar","last_name değişkenini oluşturur ve Chen metnini saklar","her değişkeni kendi satırında yazdırır"]$q$::jsonb
  ),
  (
    $q$py-u02-l2-q6$q$,
    $q$python$q$,
    $q$py-u02-l2$q$,
    $q$# Store three different types
age = 30
height = 5.9
city = "Berlin"
print(age)
print(height)
print(city)$q$,
    $q$# Üç farklı türü sakla
age = 30
height = 5.9
city = "Berlin"
print(age)
print(height)
print(city)$q$,
    $q$["stores the whole number 30 in age (int type)","stores the decimal number 5.9 in height (float type)","stores the text Berlin in city (str type)","prints each variable"]$q$::jsonb,
    $q$["tam sayı 30'u age'de saklar (int türü)","ondalık sayı 5.9'u height'ta saklar (float türü)","metin Berlin'i city'de saklar (str türü)","her değişkeni yazdırır"]$q$::jsonb
  ),
  (
    $q$py-u02-l3-q6$q$,
    $q$python$q$,
    $q$py-u02-l3$q$,
    $q$# Convert and check types
original = "99"
converted = int(original)
print(type(original))
print(type(converted))$q$,
    $q$# Dönüştür ve türleri kontrol et
original = "99"
converted = int(original)
print(type(original))
print(type(converted))$q$,
    $q$["stores the string \"99\" in original","converts it to the int 99 and stores in converted","type(original) shows the first is a str","type(converted) shows the second is an int"]$q$::jsonb,
    $q$["string \"99\"'u original'da saklar","onu int 99'a dönüştürür ve converted'e saklar","type(original) birincinin str olduğunu gösterir","type(converted) ikincinin int olduğunu gösterir"]$q$::jsonb
  ),
  (
    $q$py-u02-l4-q6$q$,
    $q$python$q$,
    $q$py-u02-l4$q$,
    $q$# Track status with booleans and absence with None
is_active = True
is_admin = False
last_login = None
print(type(is_active))
print(type(is_admin))
print(type(last_login))$q$,
    $q$# Boolean'larla durumu ve None ile yokluğu takip et
is_active = True
is_admin = False
last_login = None
print(type(is_active))
print(type(is_admin))
print(type(last_login))$q$,
    $q$["stores True in is_active (boolean type)","stores False in is_admin (boolean type)","stores None in last_login (NoneType)","prints the type of each variable"]$q$::jsonb,
    $q$["True'yu is_active'e saklar (boolean türü)","False'u is_admin'e saklar (boolean türü)","None'ı last_login'e saklar (NoneType)","her değişkenin türünü yazdırır"]$q$::jsonb
  ),
  (
    $q$py-u03-l1-q6$q$,
    $q$python$q$,
    $q$py-u03-l1$q$,
    $q$# Builds a decorative line
line = "*" * 10 + "-" * 3 + "*" * 10
print(line)$q$,
    $q$# Dekoratif bir satır oluşturur
line = "*" * 10 + "-" * 3 + "*" * 10
print(line)$q$,
    $q$["repeats the asterisk 10 times","repeats the hyphen 3 times","joins them together with +","prints the combined pattern"]$q$::jsonb,
    $q$["yıldızı 10 kez tekrarlar","tireyi 3 kez tekrarlar","onları + ile birleştirir","birleşen deseni yazdırır"]$q$::jsonb
  ),
  (
    $q$py-u03-l2-q6$q$,
    $q$python$q$,
    $q$py-u03-l2$q$,
    $q$# Displays the first and last character of a word
word = "hello"
print(word[0])
print(word[-1])$q$,
    $q$# Bir kelimenin ilk ve son karakterini gösterir
word = "hello"
print(word[0])
print(word[-1])$q$,
    $q$["stores hello in word","accesses the first character with [0]","accesses the last character with [-1]","prints each one on a separate line"]$q$::jsonb,
    $q$["hello'yu word'e saklar","[0] ile ilk karaktere erişir","[-1] ile son karaktere erişir","her birini ayrı satırda yazdırır"]$q$::jsonb
  ),
  (
    $q$py-u03-l3-q6$q$,
    $q$python$q$,
    $q$py-u03-l3$q$,
    $q$# Splits a date into year, month, and day
date = "2024-08-18"
year = date[0:4]
month = date[5:7]
day = date[8:10]
print(year, month, day)$q$,
    $q$# Bir tarihi yıl, ay ve güne ayırır
date = "2024-08-18"
year = date[0:4]
month = date[5:7]
day = date[8:10]
print(year, month, day)$q$,
    $q$["slices the year from date[0:4]","slices the month from date[5:7]","slices the day from date[8:10]","prints all three values together"]$q$::jsonb,
    $q$["date[0:4] ile yılı dilimler","date[5:7] ile ayı dilimler","date[8:10] ile günü dilimler","üç değeri birlikte yazdırır"]$q$::jsonb
  ),
  (
    $q$py-u03-l4-q6$q$,
    $q$python$q$,
    $q$py-u03-l4$q$,
