full_name = "  Alice Johnson  "
clean = full_name.strip().lower()
username = clean.replace(" ", "_")
print(f"Username: {username}")$q$,
    $q$# Tam bir addan kullanıcı adı oluşturur
full_name = "  Alice Johnson  "
clean = full_name.strip().lower()
username = clean.replace(" ", "_")
print(f"Username: {username}")$q$,
    $q$["removes leading and trailing spaces with strip()","converts to lowercase with lower()","replaces spaces with underscores using replace()","uses an f-string to display the final username"]$q$::jsonb,
    $q$["strip() ile başındaki ve sonundaki boşlukları kaldırır","lower() ile küçük harfe çevirir","replace() ile boşlukları alt çizgilerle değiştirir","son kullanıcı adını göstermek için f-string kullanır"]$q$::jsonb
  ),
  (
    $q$py-u04-l1-q6$q$,
